  templates.push(templatesAll[ti].json);
}

var configData = Array.isArray(sysConfigArr) ? sysConfigArr[0] : sysConfigArr;
var fields = [];
if (configData && configData.setting && configData.setting.fields) {
  fields = configData.setting.fields;
}

var userFields = [];
var extraAliases = {
  'first_name': ['first name', 'forename', 'given name', 'firstname', 'applicant name'],
  'last_name': ['last name', 'surname', 'family name', 'lastname'],
  'phone_number': ['phone number', 'telephone number', 'telephone', 'tel number', 'landline', 'contact number'],
  'email': ['email', 'email address', 'e-mail', 'e mail'],
  'company_name': ['company', 'company name', 'organisation', 'organization', 'business name'],
  'company_number': ['company number', 'company no', 'registration number', 'company reg'],
  'company_address': ['company address', 'business address', 'registered address'],
  'website': ['website', 'web site', 'url'],
  'mobile_number': ['mobile', 'mobile number', 'mobile no', 'cell phone', 'mob number'],
  'postcode': ['postcode', 'post code', 'zip code', 'zip', 'pcode', 'p code'],
  'title': ['title', 'salutation', 'prefix'],
  'position': ['position', 'job title', 'role']
};

for (var i = 0; i < fields.length; i++) {
  var f = fields[i];
  var aliases = [f.key.replace(/_/g, ' ')];
  if (f.label) { aliases.push(f.label.toLowerCase()); }
  var extra = extraAliases[f.key];
  if (extra) {
    for (var ei = 0; ei < extra.length; ei++) {
      if (aliases.indexOf(extra[ei]) < 0) { aliases.push(extra[ei]); }
    }
  }
  userFields.push({ key: f.key, source: f.source || 'users', aliases: aliases, category: 'user_data' });
}

var resultsFields = [];

function addR(key, aliases, cat) {
  var all = [key.split('.').pop().replace(/_/g, ' ')];
  for (var a = 0; a < aliases.length; a++) {
    if (all.indexOf(aliases[a]) < 0) { all.push(aliases[a]); }
  }
  resultsFields.push({ key: 'results.' + key, source: 'results', aliases: all, category: cat || 'results' });
}

