var data = $input.first().json;
var templates = data.templates;
var refDict = data.reference_dictionary;
var MIN_SCORE = data.min_score || 0.70;
var MIN_ALIAS_LEN = 4;

function levenshtein(a, b) {
  var m = a.length, n = b.length;
  var dp = [];
  for (var i = 0; i <= m; i++) {
    dp[i] = [i];
    for (var j = 1; j <= n; j++) { dp[i][j] = 0; }
  }
  for (var j2 = 0; j2 <= n; j2++) { dp[0][j2] = j2; }
  for (var i2 = 1; i2 <= m; i2++) {
    for (var j3 = 1; j3 <= n; j3++) {
      var cost = (a[i2-1] === b[j3-1]) ? 0 : 1;
      dp[i2][j3] = Math.min(dp[i2-1][j3] + 1, dp[i2][j3-1] + 1, dp[i2-1][j3-1] + cost);
    }
  }
  return dp[m][n];
}

function similarity(a, b) {
  var maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1;
  return 1 - levenshtein(a, b) / maxLen;
}

function normalise(name) {
  // Extract leaf from dot-separated hierarchical paths
  var dotParts = name.split('.');
  name = dotParts[dotParts.length - 1];
  // Strip array indices [0], [1] etc.
  name = name.replace(/\[\d+\]/g, '');
  // Strip common PDF form section prefixes
  name = name.replace(/^(APP|AD|Agent|DPW|SA|SiteArea|Parking|Trees|Access|Materials|Auth|Dec|COS)_/i, '');
  // Split camelCase into words
  name = name.replace(/([a-z])([A-Z])/g, '$1 $2');
  return name
    .replace(/^[A-Z0-9]+-/i, '')
    .replace(/[_-]/g, ' ')
    .replace(/\d+$/g, '')
    .replace(/[^a-zA-Z0-9 ]/g, '')
    .toLowerCase()
    .trim();
}

function findBestMatch(norm, refDict, minScore) {
  var bestScore = 0;
  var bestEntry = null;
  var bestAlias = '';
  var matchType = '';

  for (var ri = 0; ri < refDict.length; ri++) {
    var ref = refDict[ri];
    for (var ai = 0; ai < ref.aliases.length; ai++) {
      var alias = ref.aliases[ai];
      var score = 0;

      if (norm === alias) {
        score = 1.0;
      } else {
        score = similarity(norm, alias);
      }

      if (score < minScore && alias.length >= MIN_ALIAS_LEN) {
        if (norm.indexOf(alias) >= 0 && alias.length >= norm.length * 0.5) {
          score = Math.max(score, 0.85);
        } else if (alias.indexOf(norm) >= 0 && norm.length >= alias.length * 0.5) {
          score = Math.max(score, 0.82);
        }
      }

      if (alias.length < MIN_ALIAS_LEN && score < 1.0) {
        score = score * 0.7;
      }

      if (score > bestScore) {
        bestScore = score;
        bestEntry = ref;
        bestAlias = alias;
        if (norm === alias) { matchType = 'exact'; }
        else if (norm.indexOf(alias) >= 0 || alias.indexOf(norm) >= 0) { matchType = 'contains'; }
        else { matchType = 'fuzzy'; }
      }
    }
  }

  if (bestScore >= minScore && bestEntry) {
    return {
      key: bestEntry.key,
      source: bestEntry.source,
      score: Math.round(bestScore * 100) / 100,
      matchType: matchType,
      matchedAlias: bestAlias,
      category: bestEntry.category
    };
  }
  return null;
}

var allRows = [];
var templateSummaries = [];
var totalFields = 0;
var totalMapped = 0;
var totalUnmapped = 0;
var totalSuggestionsFound = 0;

for (var ti = 0; ti < templates.length; ti++) {
  var tpl = templates[ti];
  var tplRef = tpl.template_ref || 'unknown';
  var tplTitle = tpl.title || '';
  var mapping = tpl.source_to_template_mapping || [];

  var tplTotal = mapping.length;
  var tplMapped = 0;
  var tplUnmapped = 0;
  var tplSuggested = 0;
  var tplTopSuggestions = [];

  for (var mi = 0; mi < mapping.length; mi++) {
    var entry = mapping[mi];
    var pdfField = entry.pdfField || '';
    var fieldType = entry.fieldType || '';
    var currentDataKey = entry.dataKey || '';
    var currentSource = entry.source || '';
    var isMapped = (currentDataKey !== '');

    if (isMapped) {
      tplMapped++;
      allRows.push({
        templateRef: tplRef,
        pdfField: pdfField,
        fieldType: fieldType,
        currentStatus: 'mapped',
        currentDataKey: currentDataKey,
        currentSource: currentSource,
        suggestedDataKey: '',
        suggestedSource: '',
        matchScore: '',
        matchType: '',
        notes: 'Already mapped to ' + currentDataKey + ' [' + currentSource + ']'
      });
    } else {
      tplUnmapped++;
      var norm = normalise(pdfField);
      var match = null;
      if (norm.length >= 3 && fieldType !== 'checkbox' && fieldType !== 'radio') {
        match = findBestMatch(norm, refDict, MIN_SCORE);
      }

      var sugKey = '';
      var sugSource = '';
      var sugScore = '';
      var sugType = '';
      var notes = '';

      if (match) {
        sugKey = match.key;
        sugSource = match.source;
        sugScore = match.score;
        sugType = match.matchType;
        notes = 'Matched alias: "' + match.matchedAlias + '" (category: ' + match.category + ')';
        tplSuggested++;
        tplTopSuggestions.push({
          pdfField: pdfField,
          suggestedKey: match.key,
          score: match.score,
          matchType: match.matchType
        });
      } else {
        if (fieldType === 'checkbox' || fieldType === 'radio') {
          notes = 'Checkbox/radio — manual mapping required';
        } else if (norm.length < 3) {
          notes = 'Field name too short for fuzzy matching';
        } else {
          notes = 'No match found above threshold (' + MIN_SCORE + ')';
        }
      }

      allRows.push({
        templateRef: tplRef,
        pdfField: pdfField,
        fieldType: fieldType,
        currentStatus: 'unmapped',
        currentDataKey: '',
        currentSource: '',
        suggestedDataKey: sugKey,
        suggestedSource: sugSource,
        matchScore: sugScore,
        matchType: sugType,
        notes: notes
      });
    }
  }

  tplTopSuggestions.sort(function(a, b) { return b.score - a.score; });

  templateSummaries.push({
    template_ref: tplRef,
    title: tplTitle,
    total_fields: tplTotal,
    mapped: tplMapped,
    unmapped: tplUnmapped,
    suggestions_found: tplSuggested,
    suggestion_rate_pct: tplUnmapped > 0 ? Math.round(tplSuggested / tplUnmapped * 100) : 100,
    top_suggestions: tplTopSuggestions.slice(0, 10)
  });

  totalFields += tplTotal;
  totalMapped += tplMapped;
  totalUnmapped += tplUnmapped;
  totalSuggestionsFound += tplSuggested;
}

return [{
  json: {
    run_id: data.run_id,
    SUPABASE_URL: data.SUPABASE_URL,
    SUPABASE_BUCKET: data.SUPABASE_BUCKET,
    allRows: allRows,
    templateSummaries: templateSummaries,
    overall: {
      templates_analysed: templates.length,
      total_fields: totalFields,
      total_mapped: totalMapped,
      total_unmapped: totalUnmapped,
      total_suggestions_found: totalSuggestionsFound,
      overall_suggestion_rate_pct: totalUnmapped > 0 ? Math.round(totalSuggestionsFound / totalUnmapped * 100) : 100,
      reference_dictionary_size: refDict.length,
      min_score_threshold: MIN_SCORE
    }
  }
}];

var data = $input.first().json;
var allRows = data.allRows || [];
var rows = [];

for (var i = 0; i < allRows.length; i++) {
  var r = allRows[i];
  rows.push({
    json: {
      'Template Ref': r.templateRef,
      'PDF Field Name': r.pdfField,
      'Field Type': r.fieldType,
      'Current Status': r.currentStatus,
      'Current Mapping': r.currentDataKey ? r.currentDataKey + ' [' + r.currentSource + ']' : '',
      'Suggested Data Key': r.suggestedDataKey,
      'Suggested Source': r.suggestedSource,
      'Match Score': r.matchScore,
      'Match Type': r.matchType,
      'Notes': r.notes
    }
  });
}

if (rows.length === 0) {
  rows.push({
    json: {
      'Template Ref': '(no templates found)',
      'PDF Field Name': '',
      'Field Type': '',
      'Current Status': '',
      'Current Mapping': '',
      'Suggested Data Key': '',
      'Suggested Source': '',
      'Match Score': '',
      'Match Type': '',
      'Notes': ''
    }
  });
}

return rows;

var data = $('Analyse Gaps').first().json;

return [{
  json: {
    jsonSummary: {
      report_type: 'gap_analysis',
      version: '0.1',
      run_id: data.run_id,
      generated_at: new Date().toISOString(),
      overall: data.overall,
      templates: data.templateSummaries
    }
  }
}];

var analysis = $('Analyse Gaps').first().json;
var jsonSummary = $('Build JSON Summary').first().json.jsonSummary;
var excelBinary = $('Write Gap Report Excel').first().binary;

var overall = analysis.overall;
var msg = 'Gap analysis complete. '
  + overall.templates_analysed + ' template(s) analysed, '
  + overall.total_fields + ' total fields ('
  + overall.total_mapped + ' mapped, '
  + overall.total_unmapped + ' unmapped). '
  + overall.total_suggestions_found + ' suggestions found ('
  + overall.overall_suggestion_rate_pct + '% suggestion rate). '
  + 'Reference dictionary: ' + overall.reference_dictionary_size + ' keys. '
  + 'Excel report uploaded to gap-reports/' + analysis.run_id + '_gap_report.xlsx';

return [{
  json: {
    status: 'success',
    message: msg,
    run_id: analysis.run_id,
    overall: overall,
    templates: analysis.templateSummaries,
    json_summary: jsonSummary,
    excel_path: 'gap-reports/' + analysis.run_id + '_gap_report.xlsx'
  },
  binary: excelBinary
}];
